}

function isNodeExecutedBefore(context: ValidationContext, beforeNodeId: string, afterNodeId: string): boolean {
  // 簡単な実装: beforeNodeからafterNodeへのパスが存在するかチェック
  const edges = Array.from(context.edgeMap.values());
