    // 各修正を順番に適用
    fixIds.forEach(fixId => {
      const handler = autoFixHandlers[fixId];
      if (handler) {
        dsl = handler(dsl);
      }
    });

    return yaml.dump(dsl, {
      indent: 2,
      lineWidth: -1,
      noRefs: true,
      sortKeys: false,
    });
  } catch (error) {
    console.error('Auto-fix error:', error);
    return dslYaml; // 修正に失敗した場合は元のYAMLを返す
  }
}

